// Tormenta20 1.6.6 ItemT20#rollDamage, copied verbatim from tormenta20.mjs (T20:7936-8019).
// Joined into a class body with new Function by the tests.
export const ROLL_DAMAGE_1_6_6 = [
  "async rollDamage({ critical = false, event = null, options = {} } = {}) {",
  "\tconst itemData = this.system;",
  "\tconst actorData = this.actor.system;",
  "\t// FLAGS",
  "\tconst hasFinesse =",
  "\t\tgame.settings.get(\"tormenta20\", \"lightFinesseWeapons\") || this.actor.getFlag(\"tormenta20\", \"acuidade\");",
  "\tconst hasShootingStyle = this.actor.getFlag(\"tormenta20\", \"estiloDisparo\");",
  "",
  "\tlet pericia;",
  "\tlet lancinante = false;",
  "\toptions.type = \"damage\";",
  "\tif (this.type === \"arma\") {",
  "\t\tcritical = itemData.rolled?.Ataque?._critical || false;",
  "\t\tpericia = itemData.rolls.find((i) => i.type === \"ataque\")?.parts[1][0];",
  "\t\t// lancinante = Object.values(itemData.upgrades)?.includes(\"lancinating\");",
  "\t\tlancinante = this.effects.some((i) => i.system.identifier == \"lancinating\");",
  "\t}",
  "\tconst recoveryTypes = new Set([\"curatpv\", \"curapm\", \"curatpm\"]);",
  "\tfor (let r of itemData.rolls) {",
  "\t\tif (r.type !== \"dano\") continue;",
  "\t\tconst isRecovery = r.parts.some((p) => recoveryTypes.has(p[1]));",
  "\t\tconst isHealing = r.parts.some((p) => p[1] === \"curapv\");",
  "\t\tconst perda = r.parts.some((p) => p[1] === \"perda\");",
  "\t\tconst isSpell = this.type === \"magia\";",
  "\t\tconst isAlchemical = this.type === \"consumivel\" && this.system.tipo === \"alchemy\";",
  "",
  "\t\tconst parts = r.parts.map(([dano, tipo, extra], index) => {",
  "\t\t\tif ([\"curatpv\", \"curapm\", \"curatpm\", \"perda\"].includes(tipo)) {",
  "\t\t\t\treturn [dano, tipo, extra];",
  "\t\t\t}",
  "\t\t\tif (this.type === \"arma\" && index == 1) {",
  "\t\t\t\tconst { empunhadura, proposito, propriedades } = this.system;",
  "\t\t\t\tconst isFinesse = empunhadura == \"leve\" || propriedades.agi;",
  "\t\t\t\tif (isFinesse && [\"padrao\", \"for\", \"des\"].includes(dano)) {",
  "\t\t\t\t\tconst { for: forca, des } = actorData.atributos;",
  "\t\t\t\t\tconst usarAcuidade = isFinesse && hasFinesse && des.value > forca.value;",
  "\t\t\t\t\tswitch (proposito) {",
  "\t\t\t\t\t\tcase \"disparo\":",
  "\t\t\t\t\t\t\tdano = hasShootingStyle ? \"@des\" : \"\";",
  "\t\t\t\t\t\t\tbreak;",
  "\t\t\t\t\t\tcase \"arremesso\":",
  "\t\t\t\t\t\t\tdano = usarAcuidade ? \"@des\" : \"@for\";",
  "\t\t\t\t\t\t\tbreak;",
  "\t\t\t\t\t\tcase \"corpo-a-corpo\":",
  "\t\t\t\t\t\tcase \"corpo-a-corpo-arremesso\":",
  "\t\t\t\t\t\tdefault:",
  "\t\t\t\t\t\t\tdano = usarAcuidade ? \"@des\" : \"@for\";",
  "\t\t\t\t\t}",
  "\t\t\t\t}",
  "\t\t\t}",
  "\t\t\treturn [dano, tipo, extra];",
  "\t\t});",
  "\t\tif (isRecovery) ; else if (isHealing) {",
  "\t\t\tconst bonuses = foundry.utils.getProperty(actorData, \"modificadores.cura\") || {};",
  "\t\t\tif (bonuses.geral?.filter(Boolean).length) parts.push([\"@curaGeral\", \"\", \"\"]);",
  "\t\t\tif (isSpell && bonuses.mag?.filter(Boolean).length) parts.push([\"@curaMagica\", \"\", \"\"]);",
  "\t\t\telse if (isAlchemical && bonuses.alq?.filter(Boolean).length) parts.push([\"@curaALQ\", \"\", \"\"]);",
  "\t\t} else if (!perda) {",
  "\t\t\tconst bonuses = foundry.utils.getProperty(actorData, \"modificadores.dano\") || {};",
  "\t\t\tif (bonuses.geral?.filter(Boolean).length) parts.push([\"@dano\", \"\", \"\"]);",
  "",
  "\t\t\tif (pericia === \"luta\" && bonuses.cac?.filter(Boolean).length) parts.push([\"@danoCAC\", \"\", \"\"]);",
  "\t\t\telse if (pericia === \"pont\" && bonuses.ad?.filter(Boolean).length) parts.push([\"@danoAD\", \"\", \"\"]);",
  "",
  "\t\t\tif (isSpell && bonuses.mag?.filter(Boolean).length) parts.push([\"@danoMagico\", \"\", \"\"]);",
  "\t\t\telse if (isAlchemical && bonuses.mag?.filter(Boolean).length) parts.push([\"@danoALQ\", \"\", \"\"]);",
  "\t\t}",
  "",
  "\t\titemData.rolled[r.name] = await damageRoll({",
  "\t\t\trd: r.rd,",
  "\t\t\tactor: this.actor,",
  "\t\t\tcritical: critical ?? false,",
  "\t\t\tcriticalMultiplier: itemData.criticoX,",
  "\t\t\tlancinante,",
  "\t\t\tdata: this.getRollData(),",
  "\t\t\tevent,",
  "\t\t\tparts,",
  "\t\t\ttitle: this.name,",
  "\t\t\tflavor: this.name,",
  "\t\t\t...options",
  "\t\t});",
  "\t}",
  "\t// return result;",
  "}"
].join("\n");
